  2	/**
  3	 * @package Application
  4	 * @subpackage Composer
  5	 */
  6	
  7	declare(strict_types=1);
  8	
  9	namespace Application\Composer\IconBuilder;
 10	
 11	use AppUtils\OperationResult;
 12	
 13	/**
 14	 * Orchestrator that reads icon definitions from a JSON source file, renders
 15	 * PHP and JS method blocks, and replaces the content between the
 16	 * {@see self::MARKER_START} and {@see self::MARKER_END} marker comments in
 17	 * the respective target files.
 18	 *
 19	 * Designed for build-time use and has no dependency on the full application
 20	 * bootstrap, the `LocalFrameworkClone`, or the `t()` translation function.
 21	 *
 22	 * @package Application
 23	 * @subpackage Composer
 24	 * @see IconsReader
 25	 * @see PHPRenderer
 26	 * @see JSRenderer
 27	 */
 28	class IconBuilder
 29	{
 30	    public const int ERROR_PHP_ICON_FILE_NOT_FOUND = 82301;
 31	    public const int ERROR_JS_ICON_FILE_NOT_FOUND = 82302;
 32	    public const int ERROR_START_MARKER_NOT_FOUND = 82303;
 33	    public const int ERROR_WRITE_FAILED = 82304;
 34	    public const int ERROR_END_MARKER_NOT_FOUND = 82305;
 35	
 36	    private const string MARKER_START = '/* START METHODS */';
 37	    private const string MARKER_END = '/* END METHODS */';
 38	
 39	    private string $iconsJsonPath;
 40	    private string $phpFilePath;
 41	    private string $jsFilePath;
 42	    private ?IconsReader $iconsReader = null;
 43	
 44	    /**
 45	     * @param string $iconsJsonPath Path to the icons.json source file.
 46	     * @param string $phpFilePath   Path to the PHP target file.
 47	     * @param string $jsFilePath    Path to the JS target file.
 48	     */
 49	    public function __construct(
 50	        string $iconsJsonPath,
 51	        string $phpFilePath,
 52	        string $jsFilePath
 53	    )
 54	    {
 55	        $this->iconsJsonPath = $iconsJsonPath;
 56	        $this->phpFilePath = $phpFilePath;
 57	        $this->jsFilePath = $jsFilePath;
 58	    }
 59	
 60	    /**
 61	     * Returns the icons reader, creating it on first access.
 62	     *
 63	     * @return IconsReader
 64	     */
 65	    public function getIcons() : IconsReader
 66	    {
 67	        if($this->iconsReader === null)
 68	        {
 69	            $this->iconsReader = new IconsReader($this->iconsJsonPath);
 70	        }
 71	
 72	        return $this->iconsReader;
 73	    }
 74	
 75	    /**
 76	     * Rebuilds the icon methods in both target PHP and JS files.
 77	     *
 78	     * Reads icon definitions from the JSON source, renders method code for
 79	     * each language, and replaces the content between the
 80	     * `START METHODS` / `END METHODS` marker comments in each target file.
 81	     *
 82	     * Returns a failed {@see OperationResult} when any of the following occur:
 83	     * - The PHP target file does not exist ({@see self::ERROR_PHP_ICON_FILE_NOT_FOUND}).
 84	     * - The JS target file does not exist ({@see self::ERROR_JS_ICON_FILE_NOT_FOUND}).
 85	     * - A start marker is absent in either target file ({@see self::ERROR_START_MARKER_NOT_FOUND}).
 86	     * - An end marker is absent in either target file ({@see self::ERROR_END_MARKER_NOT_FOUND}).
 87	     * - Writing a target file fails (e.g. read-only file, full disk) ({@see self::ERROR_WRITE_FAILED}).
 88	     *
 89	     * @return OperationResult
 90	     */
 91	    public function build() : OperationResult
 92	    {
 93	        $result = new OperationResult($this);
 94	
 95	        if(!file_exists($this->phpFilePath))
 96	        {
 97	            return $result->makeError(
 98	                sprintf('PHP icon file not found: [%s].', $this->phpFilePath),
 99	                self::ERROR_PHP_ICON_FILE_NOT_FOUND
100	            );

101	        }
102	
103	        if(!file_exists($this->jsFilePath))
104	        {
105	            return $result->makeError(
106	                sprintf('JS icon file not found: [%s].', $this->jsFilePath),
107	                self::ERROR_JS_ICON_FILE_NOT_FOUND
108	            );
109	        }
110	
111	        $icons = $this->getIcons();
112	
113	        $phpResult = $this->insertIconCode(
114	            $this->phpFilePath,
115	            (new PHPRenderer($icons))->render(),
116	            $result
117	        );
118	
119	        if(!$phpResult->isValid())
120	        {
121	            return $phpResult;
122	        }
123	
124	        $jsResult = $this->insertIconCode(
125	            $this->jsFilePath,
126	            (new JSRenderer($icons))->render(),
127	            $result
128	        );
129	
130	        if(!$jsResult->isValid())
131	        {
132	            return $jsResult;
133	        }
134	
135	        return $result->makeSuccess(sprintf(
136	            'Successfully rebuilt icon methods from [%s].',
137	            basename($this->iconsJsonPath)
138	        ));
139	    }
140	
141	    /**
142	     * Reads the target file, replaces the content between
143	     * {@see self::MARKER_START} and {@see self::MARKER_END} with the
144	     * rendered code, and writes the result back to the file.
145	     *
146	     * Sets the supplied result to an error state and returns it when either
147	     * marker is absent from the file.
148	     *
149	     * @param string $filePath  Absolute path of the target file.
150	     * @param string $rendered  Rendered method code to insert between the markers.
151	     * @param OperationResult $result Shared result instance for error reporting.
152	     * @return OperationResult The same result instance (possibly set to error).
153	     */
154	    private function insertIconCode(string $filePath, string $rendered, OperationResult $result) : OperationResult
155	    {
156	        $content = (string)file_get_contents($filePath);
157	
158	        $startPos = strpos($content, self::MARKER_START);
159	
160	        if($startPos === false)
161	        {
162	            return $result->makeError(
163	                sprintf(
164	                    'Start marker [%s] not found in file [%s].',
165	                    self::MARKER_START,
166	                    $filePath
167	                ),
168	                self::ERROR_START_MARKER_NOT_FOUND
169	            );
170	        }
171	
172	        $endPos = strpos($content, self::MARKER_END);
173	
174	        if($endPos === false)
175	        {
176	            return $result->makeError(
177	                sprintf(
178	                    'End marker [%s] not found in file [%s].',
179	                    self::MARKER_END,
180	                    $filePath
181	                ),
182	                self::ERROR_END_MARKER_NOT_FOUND
183	            );
184	        }
185	
186	        $afterStart = $startPos + strlen(self::MARKER_START);
187	
188	        $newContent =
189	            substr($content, 0, $afterStart) .
190	            $rendered .
191	            substr($content, $endPos);
192	
193	        // @ suppresses the native PHP warning; the return value is the authoritative failure signal.
194	        $written = @file_put_contents($filePath, $newContent);
195	
196	        if($written === false)
197	        {
198	            return $result->makeError(
199	                sprintf('Failed to write to file [%s].', $filePath),
200	                self::ERROR_WRITE_FAILED
201	            );
202	        }
203	
204	        return $result;
205	    }
206	}

