  7	use Application\Composer\IconBuilder\IconBuilder;
  8	use AppFrameworkTestClasses\ApplicationTestCase;
  9	
 10	/**
 11	 * Unit tests for {@see IconBuilder}.
 12	 *
 13	 * Each test that needs valid PHP/JS target files creates temporary copies in
 14	 * the system temp directory. The {@see tearDown()} method removes them after
 15	 * every test so no artefacts linger between runs.
 16	 */
 17	final class IconBuilderTest extends ApplicationTestCase
 18	{
 19	    // -------------------------------------------------------------------------
 20	    // Fixtures & helpers
 21	    // -------------------------------------------------------------------------
 22	
 23	    /**
 24	     * Path to the framework's own icons.json – used as a real JSON source.
 25	     */
 26	    private string $iconsJsonPath = '';
 27	
 28	    /**
 29	     * @var string[]
 30	     */
 31	    private array $tempFiles = array();
 32	
 33	    protected function setUp() : void
 34	    {
 35	        parent::setUp();
 36	
 37	        $this->iconsJsonPath = realpath(
 38	            __DIR__ . '/../../../../src/themes/default/icons.json'
 39	        );
 40	
 41	        $this->assertNotFalse(
 42	            $this->iconsJsonPath,
 43	            'Fixture icons.json could not be resolved.'
 44	        );
 45	    }
 46	
 47	    protected function tearDown() : void
 48	    {
 49	        foreach($this->tempFiles as $path)
 50	        {
 51	            if(file_exists($path))
 52	            {
 53	                unlink($path);
 54	            }
 55	        }
 56	
 57	        $this->tempFiles = array();
 58	
 59	        parent::tearDown();
 60	    }
 61	
 62	    /**
 63	     * Creates a temporary file with optional initial content and registers it
 64	     * for cleanup. Returns the absolute path to the created file.
 65	     *
 66	     * @param string $content
 67	     * @return string
 68	     */
 69	    private function createTempFile(string $content = '') : string
 70	    {
 71	        $path = tempnam(sys_get_temp_dir(), 'icon_builder_test_');
 72	        file_put_contents($path, $content);
 73	        $this->tempFiles[] = $path;
 74	        return $path;
 75	    }
 76	
 77	    /**
 78	     * Returns minimal PHP file content containing the required markers with
 79	     * placeholder content between them.
 80	     *
 81	     * @return string
 82	     */
 83	    private function phpFileWithMarkers() : string
 84	    {
 85	        return implode(PHP_EOL, array(
 86	            '<?php',
 87	            'class TestIcon {',
 88	            '    /* START METHODS */',
 89	            '',
 90	            '    // region: Icon methods',
 91	            '    public function placeholder() : self {}',
 92	            '    // endregion',
 93	            '',
 94	            '    /* END METHODS */',
 95	            '}',
 96	        ));
 97	    }
 98	
 99	    /**
100	     * Returns minimal JS file content containing the required markers with

101	     * placeholder content between them.
102	     *
103	     * @return string
104	     */
105	    private function jsFileWithMarkers() : string
106	    {
107	        return implode(PHP_EOL, array(
108	            'var TestIcon = {',
109	            '    /* START METHODS */',
110	            '',
111	            '    // region: Icon methods',
112	            '    Placeholder:function() {},',
113	            '    // endregion',
114	            '',
115	            '    /* END METHODS */',
116	            '};',
117	        ));
118	    }
119	
120	    /**
121	     * Creates a valid IconBuilder pointing at temporary files that each contain
122	     * the required `START METHODS` / `END METHODS` markers.
123	     *
124	     * @return array{0: IconBuilder, 1: string, 2: string}
125	     *   Returns the builder and the paths to the temp PHP and JS files.
126	     */
127	    private function builderWithMarkerFiles() : array
128	    {
129	        $phpPath = $this->createTempFile($this->phpFileWithMarkers());
130	        $jsPath  = $this->createTempFile($this->jsFileWithMarkers());
131	
132	        return array(
133	            new IconBuilder($this->iconsJsonPath, $phpPath, $jsPath),
134	            $phpPath,
135	            $jsPath,
136	        );
137	    }
138	
139	    // -------------------------------------------------------------------------
140	    // build() – success path
141	    // -------------------------------------------------------------------------
142	
143	    public function test_build_succeedsWithValidFiles() : void
144	    {
145	        list($builder) = $this->builderWithMarkerFiles();
146	
147	        $result = $builder->build();
148	
149	        $this->assertTrue(
150	            $result->isValid(),
151	            'Expected build() to return a valid OperationResult, got: ' . $result->getMessage()
152	        );
153	    }
154	
155	    public function test_build_replacesMarkerContent() : void
156	    {
157	        list($builder, $phpPath, $jsPath) = $this->builderWithMarkerFiles();
158	
159	        $builder->build();
160	
161	        $phpContent = (string)file_get_contents($phpPath);
162	        $jsContent  = (string)file_get_contents($jsPath);
163	
164	        // Placeholder methods must have been replaced.
165	        $this->assertStringNotContainsString(
166	            'placeholder()',
167	            $phpContent,
168	            'Expected placeholder PHP method to be replaced by the builder.'
169	        );
170	        $this->assertStringNotContainsString(
171	            'Placeholder:function()',
172	            $jsContent,
173	            'Expected placeholder JS method to be replaced by the builder.'
174	        );
175	
176	        // The markers themselves must still be present.
177	        $this->assertStringContainsString('/* START METHODS */', $phpContent);
178	        $this->assertStringContainsString('/* END METHODS */', $phpContent);
179	        $this->assertStringContainsString('/* START METHODS */', $jsContent);
180	        $this->assertStringContainsString('/* END METHODS */', $jsContent);
181	    }
182	
183	    public function test_build_generatesKnownPhpMethod() : void
184	    {
185	        list($builder, $phpPath) = $this->builderWithMarkerFiles();
186	
187	        $builder->build();
188	
189	        $phpContent = (string)file_get_contents($phpPath);
190	
191	        // "add" is a well-known icon present in the framework's icons.json.
192	        $this->assertStringContainsString(
193	            "public function add() : self",
194	            $phpContent
195	        );
196	    }
197	
198	    public function test_build_generatesKnownJsMethod() : void
199	    {
200	        list($builder, , $jsPath) = $this->builderWithMarkerFiles();
201	
202	        $builder->build();
203	
204	        $jsContent = (string)file_get_contents($jsPath);
205	
206	        // "add" icon → PascalCase "Add" in JS.
207	        $this->assertStringContainsString(
208	            "Add:function()",
209	            $jsContent
210	        );
211	    }
