214	    // build() – getIcons()
215	    // -------------------------------------------------------------------------
216	
217	    public function test_getIcons_returnsIconsReader() : void
218	    {
219	        list($builder) = $this->builderWithMarkerFiles();
220	
221	        $builder->build();
222	
223	        $this->assertGreaterThan(0, $builder->getIcons()->countIcons());
224	    }
