246	    // build() – missing JS file
247	    // -------------------------------------------------------------------------
248	
249	    public function test_build_jsFileMissing_returnsError() : void
250	    {
251	        $phpPath = $this->createTempFile($this->phpFileWithMarkers());
252	        $builder = new IconBuilder(
253	            $this->iconsJsonPath,
254	            $phpPath,
255	            '/nonexistent/path/icon.js'
256	        );
257	
258	        $result = $builder->build();
259	
260	        $this->assertFalse($result->isValid());
261	        $this->assertSame(IconBuilder::ERROR_JS_ICON_FILE_NOT_FOUND, $result->getCode());
262	    }
263	
264	    // -------------------------------------------------------------------------
265	    // build() – missing markers
266	    // -------------------------------------------------------------------------
267	
268	    public function test_build_phpStartMarkerMissing_returnsError() : void
269	    {
270	        $phpPath = $this->createTempFile('<?php class TestIcon { public function foo() {} }');
271	        $jsPath  = $this->createTempFile($this->jsFileWithMarkers());
272	        $builder = new IconBuilder($this->iconsJsonPath, $phpPath, $jsPath);
273	
274	        $result = $builder->build();
275	
276	        $this->assertFalse($result->isValid());
277	        $this->assertSame(IconBuilder::ERROR_START_MARKER_NOT_FOUND, $result->getCode());
278	    }
279	
280	    public function test_build_jsStartMarkerMissing_returnsError() : void
281	    {
282	        $phpPath = $this->createTempFile($this->phpFileWithMarkers());
283	        $jsPath  = $this->createTempFile('var TestIcon = { Foo:function() {} };');
284	        $builder = new IconBuilder($this->iconsJsonPath, $phpPath, $jsPath);
